set <math>\angle BDC  = \theta  </math>

<math>BD = 2*DP = 2*43*\cos{\theta}</math>

<math>AB = \frac{BD}{\cos{\angle {DBA}}} = \frac{BD}{\cos{\theta}}=   2 \cdot 43 \cdot \frac{\cos{\theta}}{\cos{\theta}}=86</math>

<math>\frac{OP}{DO}=\frac{CP}{AD}</math>

<math>\frac{11}{43\cdot \cos{\theta}-11}=\frac{43\cdot\sin{\theta}}{86\cdot \sin{\theta}}</math>

<math>\cos{\theta}=\frac{33}{43}</math>

<math>AD=86\cdot \sin{\theta}=2 \sqrt{760}=4\sqrt{190}=\boxed{\textbf{(D)}194}</math>.

